/* falcon-bios, the station (docs/DESIGN.md Section 13): stage 3's entry
 * point in falcon-bios-station-stage3.bin.
 *
 * The station itself is falcon-bios's station/station.c, which
 * station-legacy runs too; this build adds nothing to it.
 */

#include <start/bios.h>

#include <station/station.h>

/* Generated by make into build/: this build's version, with the station-
 * variant, so a photo of the screen says which loader it is. */
#include <version.h>

static const station_app k_app = {
    "station", u"falcon-boot " FALCON_VERSION_STATION,
    0, 0
};

void bios_main(uint8_t drive)
{
    station_main(drive, &k_app);
}
